27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
61	    private Set<Pet> pets;
62	
63	    public String getAddress() {
64	        return this.address;
65	    }
66	
67	    public void setAddress(String address) {
68	        this.address = address;
69	    }
70	
71	    public String getCity() {
72	        return this.city;
73	    }
74	
75	    public void setCity(String city) {
76	        this.city = city;
77	    }
78	
79	    public String getTelephone() {
80	        return this.telephone;
81	    }
82	
83	    public void setTelephone(String telephone) {
84	        this.telephone = telephone;
85	    }
86	
87	    public String getEmail() {
88	        return this.email;
89	    }
90	
91	    public void setEmail(String email) {
92	        this.email = email;
93	    }
94	
95	    public LocalDate getRegistrationDate() {
96	        return this.registrationDate;
97	    }
98	
99	    public void setRegistrationDate(LocalDate registrationDate) {
100	        this.registrationDate = registrationDate;
101	    }
102	
103	    public String getCustomerCode() {
104	        return this.customerCode;
105	    }
106	
107	    public void setCustomerCode(String customerCode) {
108	        this.customerCode = customerCode;
109	    }
110	
111	    /**
112	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
113	     */
114	    @Transient
115	    public String getDisplayName() {
116	        return this.getLastName() + ", " + this.getFirstName();
117	    }
118	
119	    /**
120	     * Return this owner's initials as the upper-cased first letters of the first and last
121	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
122	     */
123	    @Transient
124	    public String getInitials() {
125	        return initial(this.getFirstName()) + initial(this.getLastName());
126	    }
127	
128	    private static String initial(String name) {
129	        return Character.toUpperCase(name.charAt(0)) + ".";
130	    }
131	
132	    protected Set<Pet> getPetsInternal() {
133	        if (this.pets == null) {
134	            this.pets = new HashSet<>();
135	        }
136	        return this.pets;
137	    }
138	
139	    protected void setPetsInternal(Set<Pet> pets) {
140	        this.pets = pets;
141	    }
142	
143	    public List<Pet> getPets() {
144	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
145	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
146	        return Collections.unmodifiableList(sortedPets);
147	    }
148	
149	    public void setPets(List<Pet> pets) {
150	        this.pets = new HashSet<>(pets);
151	    }
152	
153	    public void addPet(Pet pet) {
154	        getPetsInternal().add(pet);
155	        pet.setOwner(this);
156	    }
157	
158	    /**
159	     * Return the Pet with the given name, or null if none found for this Owner.
160	     *
161	     * @param name to test
162	     * @return true if pet name is already in use
163	     */
164	    public Pet getPet(String name) {
165	        return getPet(name, false);
166	    }
167	
168	    /**
169	     * Return the Pet with the given name, or null if none found for this Owner.
170	     *
171	     * @param name to test
172	     * @return true if pet name is already in use
173	     */
174	    public Pet getPet(String name, boolean ignoreNew) {
175	        name = name.toLowerCase();
176	        for (Pet pet : getPetsInternal()) {
177	            if (!ignoreNew || !pet.isNew()) {
178	                String compName = pet.getName();
179	                compName = compName.toLowerCase();
180	                if (compName.equals(name)) {
181	                    return pet;
182	                }
183	            }
184	        }
185	        return null;
186	    }
187	
188	    public Pet getPet(Integer petId) {
189	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
190	    }
191	
192	    @Override
193	    public String toString() {
194	        return new ToStringCreator(this)
195	
196	            .append("id", this.getId())
197	            .append("new", this.isNew())
198	            .append("lastName", this.getLastName())
199	            .append("firstName", this.getFirstName())
200	            .append("address", this.address)
201	            .append("city", this.city)
202	            .append("telephone", this.telephone)
203	            .append("email", this.email)
204	            .append("registrationDate", this.registrationDate)
205	            .toString();
206	    }
207	}
