21	/**
22	 * Signals that an owner request omitted or left blank one or more required fields.
23	 *
24	 * <p>Carries the names of the offending fields so the exception handler can report
25	 * them back to the client in the {@code errors} array of the error response.
26	 */
27	public class MissingOwnerFieldsException extends RuntimeException {
28	
29	    private final List<String> missingFields;
30	
31	    public MissingOwnerFieldsException(List<String> missingFields) {
32	        super("Missing or blank required fields: " + missingFields);
33	        this.missingFields = List.copyOf(missingFields);
34	    }
35	
36	    public List<String> getMissingFields() {
37	        return missingFields;
38	    }
39	}
