17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerHouseholdException;
33	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerTelephoneException;
34	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
35	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
36	import org.springframework.samples.petclinic.rest.controller.MissingOwnerFieldsException;
37	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
38	import org.springframework.security.access.AccessDeniedException;
39	import org.springframework.validation.BindingResult;
40	import org.springframework.validation.FieldError;
41	import org.springframework.web.bind.MethodArgumentNotValidException;
42	import org.springframework.web.bind.annotation.ControllerAdvice;
43	import org.springframework.web.bind.annotation.ExceptionHandler;
44	import org.springframework.web.bind.annotation.ResponseBody;
45	
46	/**
47	 * Global Exception handler for REST controllers.
48	 * <p>
49	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
50	 *
51	 * @author Vitaliy Fedoriv
52	 * @author Alexander Dudkin
53	 */
54	@ControllerAdvice
55	public class ExceptionControllerAdvice {
56	
57	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
58	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
59	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
60	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
61	
62	    /**
63	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
64	     * class.
65	     *
66	     * @param e     Object referring to the thrown exception.
67	     * @param status HTTP response status.
68	     * @param url URL request.
69	     */
70	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
71	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
72	        problemDetail.setType(URI.create(url.toString()));
73	        problemDetail.setTitle(e.getClass().getSimpleName());
74	        problemDetail.setDetail(detail);
75	        problemDetail.setProperty("timestamp", Instant.now());
76	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
77	        return problemDetail;
78	    }
79	
80	    /**
81	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
82	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
83	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
84	     * would catch it and report an authorization failure as a 500.
85	     *
86	     * @param e The {@link AccessDeniedException} to propagate
87	     * @throws AccessDeniedException always
88	     */
89	    @ExceptionHandler(AccessDeniedException.class)
90	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
91	        throw e;
92	    }
93	
94	    /**
95	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
96	     *
97	     * @param e The {@link Exception} to be handled
98	     * @param request {@link HttpServletRequest} object referring to the current request.
99	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
100	     */
101	    @ExceptionHandler(Exception.class)
102	    @ResponseBody
103	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
104	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
105	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
106	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
107	        return ResponseEntity.status(status).body(detail);
108	    }
109	
110	    /**
111	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
112	     * method returns a 404 Not Found status if an entity does not exist.
113	     *
114	     * @param e The {@link DataIntegrityViolationException} to be handled
115	     * @param request {@link HttpServletRequest} object referring to the current request.
116	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
117	     */
118	    @ExceptionHandler(DataIntegrityViolationException.class)
119	    @ResponseBody
120	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
121	        logger.warn("Data integrity violation at {} {}: {}",
122	            request.getMethod(),
123	            request.getRequestURI(),
124	            e.getMessage());
125	        logger.debug("Data integrity violation stacktrace", e);
126	        HttpStatus status = HttpStatus.NOT_FOUND;
127	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
128	        return ResponseEntity.status(status).body(detail);
129	    }
130	
131	    /**
132	     * Handles exception thrown by Bean Validation on controller methods parameters
133	     *
134	     * @param e The {@link MethodArgumentNotValidException} to be handled
135	     * @param request {@link HttpServletRequest} object referring to the current request.
136	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
137	     */
138	    @ExceptionHandler(MethodArgumentNotValidException.class)
139	    @ResponseBody
140	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
141	        HttpStatus status = HttpStatus.BAD_REQUEST;
142	        BindingErrorsResponse errors = new BindingErrorsResponse();
143	        BindingResult bindingResult = e.getBindingResult();
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
145	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
146	            .map(FieldError::getField)
147	            .distinct()
148	            .toList());
149	        if (bindingResult.hasErrors()) {
150	            errors.addAllErrors(bindingResult);
151	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
152	                .map(fieldError -> {
153	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
154	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
155	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
156	                        fieldError.getField(),
157	                        defaultMessage,
158	                        rejectedValue);
159	                    return new ValidationMessageDto(message)
160	                        .putAdditionalProperty("field", fieldError.getField())
161	                        .putAdditionalProperty("rejectedValue", rejectedValue)
162	                        .putAdditionalProperty("defaultMessage", defaultMessage);
163	                })
164	                .toList();
165	            logger.debug("Validation error at {} {}: {}",
166	                request.getMethod(),
167	                request.getRequestURI(),
168	                bindingResult.getFieldErrors());
169	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
170	            return ResponseEntity.status(status).body(detail);
171	        }
172	        return ResponseEntity.status(status).body(detail);
173	    }
174	
175	    /**
176	     * Handles {@link MissingOwnerFieldsException} raised when an owner request omits or
177	     * leaves blank one or more required fields. Returns a 400 Bad Request whose
178	     * {@code errors} array names each offending field.
179	     *
180	     * @param e The {@link MissingOwnerFieldsException} to be handled
181	     * @param request {@link HttpServletRequest} object referring to the current request.
182	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
183	     */
184	    @ExceptionHandler(MissingOwnerFieldsException.class)
185	    @ResponseBody
186	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
187	        HttpStatus status = HttpStatus.BAD_REQUEST;
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
189	        detail.setProperty("errors", e.getMissingFields());
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link InvalidTelephoneException} raised when an owner request supplies a
195	     * telephone number that is not exactly ten digits after stripping non-digit
196	     * characters. Returns a 400 Bad Request whose {@code errors} array names the
197	     * {@code telephone} field.
198	     *
199	     * @param e The {@link InvalidTelephoneException} to be handled
200	     * @param request {@link HttpServletRequest} object referring to the current request.
201	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
202	     */
203	    @ExceptionHandler(InvalidTelephoneException.class)
204	    @ResponseBody
205	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
206	        HttpStatus status = HttpStatus.BAD_REQUEST;
207	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
208	        detail.setProperty("errors", List.of("telephone"));
209	        return ResponseEntity.status(status).body(detail);
210	    }
211	
212	    /**
213	     * Handles {@link InvalidEmailException} raised when an owner request supplies an email
214	     * address that is not syntactically valid. Returns a 400 Bad Request whose
215	     * {@code errors} array names the {@code email} field.
216	     *
217	     * @param e The {@link InvalidEmailException} to be handled
218	     * @param request {@link HttpServletRequest} object referring to the current request.
219	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
220	     */
221	    @ExceptionHandler(InvalidEmailException.class)
222	    @ResponseBody
223	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
224	        HttpStatus status = HttpStatus.BAD_REQUEST;
225	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
226	        detail.setProperty("errors", List.of("email"));
227	        return ResponseEntity.status(status).body(detail);
228	    }
229	
230	    /**
231	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner request supplies a
232	     * telephone number whose normalized value is already used by an existing owner. Returns a
233	     * 409 Conflict whose {@code errors} array names the {@code telephone} field.
234	     *
235	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
236	     * @param request {@link HttpServletRequest} object referring to the current request.
237	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
238	     */
239	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
240	    @ResponseBody
241	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
242	        HttpStatus status = HttpStatus.CONFLICT;
243	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
244	        detail.setProperty("errors", List.of("telephone"));
245	        return ResponseEntity.status(status).body(detail);
246	    }
247	
248	    /**
249	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner request would
250	     * create an owner whose last name and address (compared case-insensitively with
251	     * collapsed whitespace) already belong to another owner, without opting in to a shared
252	     * household. Returns a 409 Conflict whose {@code errors} array names the {@code lastName}
253	     * and {@code address} fields.
254	     *
255	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
256	     * @param request {@link HttpServletRequest} object referring to the current request.
257	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
258	     */
259	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
260	    @ResponseBody
261	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
262	        HttpStatus status = HttpStatus.CONFLICT;
263	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
264	        detail.setProperty("errors", List.of("lastName", "address"));
265	        return ResponseEntity.status(status).body(detail);
266	    }
